INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('c7d3e13f-3ff4-40f1-82f0-360aef6a9c2a', 'who-we-are', '{"visionAr": "مجتمع مسلم ممكّن رقمياً، موحد ومزدهر، يساهم في تطوير رواندا.", "visionEn": "A digitally empowered, unified, and prosperous Muslim community contributing to the development of Rwanda.", "visionRw": "Umuryango w''Abasilamu uhuye, ukoresheje ikoranabuhanga kandi ugira inyungu, utera inkunga iterambere rya Rwanda.", "missionAr": "توحيد وخدمة المجتمع المسلم في رواندا من خلال الابتكار الرقمي، وتعزيز القيم الإسلامية والتعليم والرعاية الاجتماعية.", "missionEn": "Unite and serve the Muslim community in Rwanda through digital innovation, promoting Islamic values, education, and social welfare.", "missionRw": "Guhuza no gukorera umuryango w''Abasilamu mu Rwanda binyuze mu buhanga bwa digital, guteza imbere indangagaciro z''Ubusilamu, uburezi n''imibereho myiza.", "membersCount": "12500", "mosquesCount": "320", "descriptionAr": "المجتمع الإسلامي الرواندي (RMC) هو المنظمة المظلة التي تمثل المسلمين في جميع مقاطعات رواندا. تأسست على مبادئ الأخوة الإسلامية، وتنسق الخدمات الدينية والتعليمية والاجتماعية لأكثر من 500,000 مسلم على الصعيد الوطني.", "descriptionEn": "The Rwanda Muslim Community (RMC) is the umbrella organization representing Muslims across all provinces of Rwanda. Founded on the principles of Islamic brotherhood, we coordinate religious, educational, and social services for over 500,000 Muslims nationwide.", "descriptionRw": "Umuryango w''Abasilamu bo mu Rwanda (RMC) ni umuryango ngengamikorere uhuza Abasilamu bose muri leta ya Rwanda. Washingwe ku mico y''ubuvandimwe bw''Ubusilamu, tuhuza serivisi z''amadini, z''uburezi n''imibereho myiza y''Abasilamu basaga 500,000 mu Rwanda.", "provincesCount": "5", "yearsOfService": "25"}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:22:58.137036+00', '2026-06-18 10:35:37.551619+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('8db84d01-1261-404c-932c-9d9a4684e2bc', 'community-impact', '{"items": [{"icon": "Users", "label": {"ar": "مسلمون", "en": "Muslims", "rw": "Abayisilamu"}, "value": 1000000, "suffix": "+"}, {"icon": "GraduationCap", "label": {"ar": "مدارس", "en": "Schools", "rw": "Amashuri"}, "value": 14, "suffix": "+"}, {"icon": "Building2", "label": {"ar": "مساجد", "en": "Masjids", "rw": "Imisigiti"}, "value": 640, "suffix": "+"}], "title": {"ar": "مجتمعنا", "en": "Our Growing", "rw": "Umuryango Wacu"}, "eyebrow": {"ar": "أثر المجتمع", "en": "Community Impact", "rw": "Ingaruka ku Muryango"}, "subtitle": {"ar": "نخدم المجتمع المسلم في جميع أنحاء رواندا", "en": "Serving the Muslim community across Rwanda", "rw": "Dukorera umuryango w''Abayisilamu mu Rwanda hose"}, "titleAccent": {"ar": "المتنامي", "en": "Community", "rw": "Ukura"}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:00.792043+00', '2026-06-18 10:35:40.928846+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('93920d73-a17a-44ed-904a-63515052c364', 'partners', '{"lede": {"ar": "يعمل المجتمع الإسلامي الرواندي جنبًا إلى جنب مع منظمات دولية وإقليمية رائدة لتعليم المجتمع المسلم في رواندا والنهوض به وخدمته.", "en": "RMC works alongside leading international and regional organizations to educate, uplift, and serve the Muslim community of Rwanda.", "rw": "RMC ikorana n''imiryango ikomeye y''amahanga n''iy''akarere mu kwigisha, guteza imbere, no gufasha umuryango w''Abayisilamu wo mu Rwanda."}, "items": [{"logo": "/partners/adef.png", "name": "ADEF", "sector": {"ar": "مؤسسة تعليمية", "en": "Education Foundation", "rw": "Ikigega cy''Uburezi"}}, {"logo": "/partners/direct-aid.png", "name": "Direct Aid", "sector": {"ar": "الشؤون الاجتماعية والتعليم", "en": "Social & Education", "rw": "Imibereho Myiza n''Uburezi"}, "website": "https://direct-aid.org/"}, {"logo": "/partners/iera.png", "name": "IERA", "sector": {"ar": "الدعوة", "en": "Dawah", "rw": "Kwamamaza Idini"}, "website": "https://iera.org/"}, {"logo": "/partners/wamy.jpg", "name": "WAMY", "sector": {"ar": "تنمية الشباب", "en": "Youth Development", "rw": "Iterambere ry''Urubyiruko"}, "website": "https://www.wamy.co.uk/"}], "title": {"ar": "شركاؤنا", "en": "Our Partners", "rw": "Abafatanyabikorwa Bacu"}, "eyebrow": {"ar": "نعمل معًا", "en": "Working Together", "rw": "Dukorera Hamwe"}, "footerNote": {"ar": "هل ترغب في الشراكة مع المجتمع الإسلامي الرواندي؟", "en": "Interested in partnering with RMC?", "rw": "Wifuza gufatanya na RMC?"}, "contactEmail": "info@rwandamuslim.org"}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:02.142291+00', '2026-06-18 10:35:42.711074+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('797ec18b-be51-494d-a9cd-15303383f563', 'updates-programs', '{"items": [{"cta": {"ar": "قدّم الآن", "en": "Apply Now", "rw": "Saba Nonaha"}, "icon": "GraduationCap", "badge": {"ar": "المنح الدراسية 2025", "en": "Scholarships 2025", "rw": "Buruse z''Amashuri 2025"}, "image": "https://images.unsplash.com/photo-1541339907198-e08756dedf3f?q=80&w=900&auto=format&fit=crop", "title": {"ar": "قدّم طلبك لبرنامج المنح الدراسية التعليمية للمجتمع الإسلامي الرواندي", "en": "Apply for the RMC Education Scholarship Program", "rw": "Saba Gahunda ya Buruse y''Uburezi ya RMC"}, "ctaHref": "/services", "imageAlt": "Graduation caps thrown in celebration", "statLabel": {"ar": "منح دراسية مُنحت", "en": "Scholarships awarded", "rw": "Buruse zatanzwe"}, "statValue": "500+", "description": {"ar": "منح دراسية كاملة وجزئية للطلاب المسلمين في جميع أنحاء رواندا — للمرحلة الابتدائية والثانوية والجامعية. يُغلق باب التقديم في 30 يونيو.", "en": "Full and partial scholarships for Muslim students across Rwanda — primary, secondary, and university levels. Applications close June 30th.", "rw": "Buruse zuzuye n''iz''igice ku banyeshuri b''Abayisilamu mu Rwanda hose — mu mashuri abanza, ayisumbuye, na kaminuza. Gusaba birangira ku itariki ya 30 Kamena."}}, {"cta": {"ar": "اعرف المزيد", "en": "Learn More", "rw": "Menya Byinshi"}, "icon": "Users", "badge": {"ar": "برامج المجتمع", "en": "Community Programs", "rw": "Gahunda z''Umuryango"}, "image": "https://images.unsplash.com/photo-1529156069898-49953e39b3ac?q=80&w=900&auto=format&fit=crop", "title": {"ar": "انضم إلى مبادراتنا للتنمية الاجتماعية في جميع أنحاء رواندا", "en": "Join Our Social Development Initiatives Across Rwanda", "rw": "Jya muri Gahunda Zacu z''Iterambere Rusange mu Rwanda Hose"}, "ctaHref": "/about", "imageAlt": "Community members gathered together", "statLabel": {"ar": "أعضاء المجتمع", "en": "Community members", "rw": "Abagize umuryango"}, "statValue": "12,500+", "description": {"ar": "دعم التمويل الأصغر، والتدريب المهني، وحملات الرعاية الصحية، ومشاريع تمكين الشباب التي تشمل المقاطعات الخمس جميعها. معًا نبني مجتمعات أقوى.", "en": "Microfinance support, vocational training, health outreach, and youth empowerment projects spanning all five provinces. Together we build stronger communities.", "rw": "Inkunga y''imari iciriritse, amahugurwa y''imyuga, serivisi z''ubuzima, n''imishinga yo guteza imbere urubyiruko mu ntara zose eshanu. Hamwe twubaka imiryango ikomeye."}}, {"cta": {"ar": "تبرّع الآن", "en": "Donate Now", "rw": "Tanga Nonaha"}, "icon": "Heart", "badge": {"ar": "ادعم رسالتنا", "en": "Support Our Mission", "rw": "Shyigikira Intego Yacu"}, "image": "https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=900&auto=format&fit=crop", "title": {"ar": "اصنع فرقًا — تبرّع للمجتمع المسلم", "en": "Make a Difference — Donate to the Muslim Community", "rw": "Gira Icyo Uhindura — Tanga Inkunga ku Muryango w''Abayisilamu"}, "ctaHref": "/donate", "imageAlt": "Hands giving a charitable donation", "statLabel": {"ar": "أسر تم دعمها", "en": "Families supported", "rw": "Imiryango yafashijwe"}, "statValue": "5,000+", "description": {"ar": "تبرّعك يدعم المساجد والمدارس والأيتام والبرامج الاجتماعية في جميع أنحاء رواندا. كل مساهمة، كبيرة كانت أم صغيرة، تبني أمة أقوى.", "en": "Your donation supports mosques, schools, orphans, and social programs across Rwanda. Every contribution, big or small, builds a stronger ummah.", "rw": "Inkunga yawe ifasha imisigiti, amashuri, imfubyi, na gahunda z''imibereho myiza mu Rwanda hose. Buri muganda, waba munini cyangwa muto, wubaka umat ukomeye."}}, {"cta": {"ar": "اكتشف المزيد", "en": "Discover More", "rw": "Sobanukirwa Byinshi"}, "icon": "Globe", "badge": {"ar": "الشؤون الدولية", "en": "International Affairs", "rw": "Imibanire Mpuzamahanga"}, "image": "https://images.unsplash.com/photo-1521791136064-7986c2920216?q=80&w=900&auto=format&fit=crop", "title": {"ar": "التعاون والشراكات الإسلامية العالمية", "en": "Global Islamic Cooperation & Partnerships", "rw": "Ubufatanye n''Imikoranire y''Abayisilamu ku Rwego rw''Isi"}, "ctaHref": "/about", "imageAlt": "International partnership handshake", "statLabel": {"ar": "شركاء عالميون", "en": "Global partners", "rw": "Abafatanyabikorwa ku isi"}, "statValue": "20+", "description": {"ar": "يتعاون المجتمع الإسلامي الرواندي مع المنظمات الإسلامية الدولية والسفارات والمنظمات غير الحكومية لتوفير المنح الدراسية والموارد والدعم العالمي للمجتمع المسلم الرواندي.", "en": "RMC collaborates with international Islamic organizations, embassies, and NGOs to bring scholarships, resources, and global support to the Rwandan Muslim community.", "rw": "RMC ifatanya n''imiryango y''Abayisilamu mpuzamahanga, ambasade, n''imiryango itari iya Leta, kugira ngo izane buruse, ibikoresho, n''inkunga mpuzamahanga ku muryango w''Abayisilamu bo mu Rwanda."}}], "heading": {"ar": "المستجدات والبرامج", "en": "Updates & Programs", "rw": "Amakuru n''Gahunda"}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:03.68209+00', '2026-06-18 10:35:44.375076+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('622fbf59-b71a-44ec-a5e1-f5a4f0eeb9c3', 'activities-events', '{"lede": {"ar": "تابع أحدث أنشطة المجتمع الإسلامي الرواندي وسجّل في مفكرتك الفعاليات المجتمعية القادمة.", "en": "Follow RMC''s most recent activities and mark your calendar for the community events ahead.", "rw": "Kurikira ibikorwa biheruka bya RMC kandi wandike mu kalendari yawe ibirori by''umuryango bizaza."}, "title": {"ar": "الأحدث والقادم", "en": "Latest & Upcoming", "rw": "Ibiheruka n’Ibizaza"}, "events": [{"date": "2026-06-20", "time": "08:00 AM", "tone": "green", "type": {"ar": "ديني", "en": "Religious", "rw": "Iyobokamana"}, "title": {"ar": "الاحتفال الوطني بعيد الأضحى", "en": "Eid al-Adha National Celebration", "rw": "Umunsi Mukuru wa Idi al-Adha ku Rwego rw''Igihugu"}, "location": "Amahoro National Stadium, Kigali", "goalAmount": 30000000, "raisedAmount": 22000000}, {"date": "2026-07-11", "time": "10:00 AM", "tone": "green", "type": {"ar": "التعليم", "en": "Education", "rw": "Uburezi"}, "title": {"ar": "حفل توزيع المنح الدراسية السنوي للمجتمع الإسلامي الرواندي", "en": "RMC Annual Scholarship Awards Ceremony", "rw": "Umuhango Ngarukamwaka wa RMC wo Gutanga Buruse z''Amashuri"}, "location": "Kigali Convention Centre", "goalAmount": 50000000, "raisedAmount": 38000000}, {"date": "2026-08-08", "time": "09:00 AM", "tone": "gold", "type": {"ar": "المجتمع", "en": "Community", "rw": "Umuryango"}, "title": {"ar": "قمة القيادة للنساء المسلمات", "en": "Muslim Women Leadership Summit", "rw": "Inama Nkuru y''Ubuyobozi bw''Abagore b''Abayisilamu"}, "location": "Serena Hotel, Kigali", "goalAmount": 15000000, "raisedAmount": 9000000}, {"date": "2026-09-26", "time": "02:00 PM", "tone": "gold", "type": {"ar": "الدعوة", "en": "Da’wah", "rw": "Idawa"}, "title": {"ar": "مسابقة تلاوة القرآن الكريم — التصفيات النهائية الوطنية", "en": "Qur’an Recitation Competition — National Finals", "rw": "Irushanwa ryo Gusoma Ikorani — Inzira za Nyuma ku Rwego rw''Igihugu"}, "location": "Grand Mosque of Kigali", "goalAmount": 12000000, "raisedAmount": 7500000}, {"date": "2026-11-14", "time": "09:00 AM", "tone": "neutral", "type": {"ar": "الحوكمة", "en": "Governance", "rw": "Imiyoborere"}, "title": {"ar": "اجتماع الجمعية العمومية للمجتمع الإسلامي الرواندي", "en": "RMC General Assembly Meeting", "rw": "Inama Rusange ya RMC"}, "location": "RMC Headquarters, Rebero", "goalAmount": 8000000, "raisedAmount": 8000000}], "eyebrow": {"ar": "الأنشطة والفعاليات", "en": "Activities & Events", "rw": "Ibikorwa n’Ibirori"}, "activities": [{"date": "June 4, 2026", "tone": "green", "image": "https://images.unsplash.com/photo-1541339907198-e08756dedf3f?q=80&w=200&auto=format&fit=crop", "title": {"ar": "المجتمع الإسلامي الرواندي يطلق المدرسة الرقمية في جميع المقاطعات", "en": "RMC Launches Digital Madrassa Across All Provinces", "rw": "RMC Yatangije Madarasa ya Digitale mu Ntara Zose"}, "excerpt": {"ar": "منصة إلكترونية جديدة للتعليم الإسلامي أصبحت متاحة الآن على مستوى البلاد، تقدّم دروسًا منظّمة في القرآن الكريم واللغة العربية لأكثر من 2,000 طفل في شهرها الأول.", "en": "A new online platform for Islamic education is now live nationwide, bringing structured Qur’an and Arabic lessons to over 2,000 children in its first month.", "rw": "Urubuga rushya rwo kuri interineti rw''uburezi bwa Kisilamu rumaze gukora mu gihugu hose, ruzana amasomo y''Ikorani n''Icyarabu ateguwe neza ku bana barenga 2,000 mu kwezi kwarwo kwa mbere."}, "gallery": ["https://images.unsplash.com/photo-1541339907198-e08756dedf3f?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1521791136064-7986c2920216?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=1280&auto=format&fit=crop"], "category": {"ar": "التعليم", "en": "Education", "rw": "Uburezi"}, "budgetUsed": 18000000, "peopleHelped": 2000}, {"date": "May 12, 2026", "tone": "gold", "image": "https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=200&auto=format&fit=crop", "title": {"ar": "توزيع طعام رمضان يصل إلى 5,000 أسرة", "en": "Ramadan Food Distribution Reaches 5,000 Families", "rw": "Igaburwa ry''Ibiribwa bya Ramadhani Rigeze ku Miryango 5,000"}, "excerpt": {"ar": "بالشراكة مع المنظمات غير الحكومية المحلية، قدّم المجتمع الإسلامي الرواندي طرودًا غذائية إلى 5,000 أسرة محتاجة في جميع أنحاء رواندا طوال شهر رمضان المبارك.", "en": "In partnership with local NGOs, RMC delivered food packages to 5,000 vulnerable families across Rwanda throughout the blessed month of Ramadan.", "rw": "Ku bufatanye n''imiryango itari iya Leta yo mu gihugu, RMC yatanze udufuka tw''ibiribwa ku miryango 5,000 ifite ubukene mu Rwanda hose mu gihe cy''ukwezi gutagatifu kwa Ramadhani."}, "gallery": ["https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1541339907198-e08756dedf3f?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1521791136064-7986c2920216?q=80&w=1280&auto=format&fit=crop"], "category": {"ar": "المجتمع", "en": "Community", "rw": "Umuryango"}, "budgetUsed": 45000000, "peopleHelped": 5000}, {"date": "April 18, 2026", "tone": "neutral", "image": "https://images.unsplash.com/photo-1521791136064-7986c2920216?q=80&w=200&auto=format&fit=crop", "title": {"ar": "انعقاد المؤتمر السنوي لتدريب الأئمة في موسانزي", "en": "Annual Imam Training Conference Held in Musanze", "rw": "Inama Ngarukamwaka yo Guhugura Abayimamu Yabereye i Musanze"}, "excerpt": {"ar": "اجتمع 120 إمامًا من جميع أنحاء رواندا في برنامج استمر ثلاثة أيام حول القيادة المجتمعية والتواصل الرقمي والرعاية الروحية.", "en": "120 imams from across Rwanda gathered for a three-day programme on community leadership, digital outreach, and pastoral care.", "rw": "Abayimamu 120 baturutse mu Rwanda hose bateranye mu gahunda y''iminsi itatu yerekeye ubuyobozi bw''umuryango, kugera ku bantu hifashishijwe ikoranabuhanga, no kwita ku bantu."}, "gallery": ["https://images.unsplash.com/photo-1521791136064-7986c2920216?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=1280&auto=format&fit=crop", "https://images.unsplash.com/photo-1541339907198-e08756dedf3f?q=80&w=1280&auto=format&fit=crop"], "category": {"ar": "القيادة", "en": "Leadership", "rw": "Ubuyobozi"}, "budgetUsed": 8500000, "peopleHelped": 120}], "eventsHeading": {"ar": "الفعاليات القادمة", "en": "Upcoming Events", "rw": "Ibirori Bizaza"}, "activitiesHeading": {"ar": "أحدث الأنشطة", "en": "Latest Activities", "rw": "Ibikorwa Biheruka"}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:05.032166+00', '2026-06-18 10:35:46.048773+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('43a20831-4694-4d2b-9ef3-a81b483646b2', 'announcements', '{"items": [{"title": {"ar": "الإعلان عن جدول صلاة عيد الأضحى", "en": "Eid al-Adha Prayer Schedule Announced", "rw": "Gahunda y''amasengesho ya Idi El-Adiha yatangajwe"}, "content": {"ar": "تُقام صلاة العيد في ملعب أماهورو الوطني وفي جميع مساجد المقاطعات صباح يوم العيد. يُرجى الحضور قبل الموعد بثلاثين دقيقة.", "en": "Eid prayers will be held at Amahoro National Stadium and all district masjids on Eid morning. Please arrive 30 minutes early.", "rw": "Amasengesho ya Idi azaberera ku Kibuga cy''imikino cya Amahoro no mu misigiti yose y''uturere mu gitondo cya Idi. Mwitabire iminota 30 mbere y''igihe."}, "priority": "high", "publishAt": "2026-06-12T08:00:00Z"}, {"title": {"ar": "مخيم صحي مجاني للمجتمع نهاية هذا الأسبوع", "en": "Free Community Health Camp This Weekend", "rw": "Inkambi y''ubuvuzi y''ubuntu mu muryango muri iki cyumweru"}, "content": {"ar": "تتوفر الفحوصات الطبية والاستشارات والأدوية مجانًا في المسجد الكبير بكيغالي يومي السبت والأحد.", "en": "Free medical check-ups, consultations, and medication will be available at the Grand Mosque of Kigali this Saturday and Sunday.", "rw": "Isuzuma ry''ubuvuzi, inama z''abaganga, n''imiti by''ubuntu bizaboneka ku Musigiti Mukuru wa Kigali kuwa gatandatu no ku cyumweru."}, "priority": "urgent", "publishAt": "2026-06-10T09:00:00Z"}, {"title": {"ar": "فتح باب التقديم لمنح المجتمع الإسلامي الرواندي", "en": "RMC Scholarship Applications Now Open", "rw": "Gusaba buruse za RMC byafunguwe"}, "content": {"ar": "باب التقديم مفتوح لمنح دراسية كاملة وجزئية للطلاب المسلمين في جميع أنحاء رواندا للعام الدراسي 2026/27. قدّم طلبك قبل الثلاثين من يونيو.", "en": "Full and partial scholarships for Muslim students across Rwanda are open for the 2026/27 academic year. Apply before June 30th.", "rw": "Buruse zuzuye n''izindi zigice ku banyeshuri b''Abayisilamu mu Rwanda hose zafunguwe ku mwaka w''amashuri wa 2026/27. Saba mbere ya tariki ya 30 Kamena."}, "priority": "normal", "publishAt": "2026-06-06T10:00:00Z"}, {"title": {"ar": "استئناف دروس القرآن الأسبوعية في مساجد المقاطعات", "en": "Weekly Qur’an Classes Resume at District Masjids", "rw": "Amasomo ya buri cyumweru ya Qurani aratangira mu misigiti y''uturere"}, "content": {"ar": "تُستأنف دروس حفظ القرآن والتجويد لجميع الأعمار هذا الأسبوع. سجّل في مسجد حيّك.", "en": "Qur’an memorization and Tajweed classes for all ages resume this week. Register at your local mosque.", "rw": "Amasomo yo kwiga Qurani ku mutwe na Tajiwidi ku bantu b''imyaka yose aratangira muri iki cyumweru. Iyandikishe ku musigiti wo aho utuye."}, "priority": "normal", "publishAt": "2026-06-02T07:30:00Z"}], "title": {"ar": "الإعلانات", "en": "Announcements", "rw": "Amatangazo"}, "subtitle": {"ar": "أحدث الأخبار والمستجدات", "en": "Latest news & updates", "rw": "Amakuru n''ibishya bigezweho"}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:06.447165+00', '2026-06-18 10:35:47.712744+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('ae5a2d06-0361-4cb1-9fbf-cc5e151a3ac5', 'social-media', '{"posts": [{"date": "2h ago", "image": "https://images.unsplash.com/photo-1529156069898-49953e39b3ac?q=80&w=600&auto=format&fit=crop", "likes": "1.2K", "handle": "Rwanda Muslim Community", "content": {"ar": "الحمد لله! جمع احتفالنا السنوي بعيد الفطر أكثر من 10,000 مسلم في ملعب أماهورو. تقبل الله صلواتنا وقوّى مجتمعنا. 🤲 #EidMubarak #RwandaMuslims", "en": "Alhamdulillah! Our annual Eid celebration brought together over 10,000 Muslims at Amahoro Stadium. May Allah accept our prayers and strengthen our community. 🤲 #EidMubarak #RwandaMuslims", "rw": "Alhamdulillah! Umunsi mukuru wa Eid wa buri mwaka wahuje Abayisilamu barenga 10,000 kuri sitade Amahoro. Allah yakire amasengesho yacu kandi akomeze umuryango wacu. 🤲 #EidMubarak #RwandaMuslims"}, "comments": "234", "platform": "facebook"}, {"date": "5h ago", "likes": "847", "handle": "@RMC_Rwanda", "content": {"ar": "تذكير 📢 يُغلق التقديم على المنح الدراسية للعام الدراسي 2025/2026 في 30 يونيو. قدّم الآن عبر موقعنا. جميع الطلاب المسلمين من رواندا مؤهلون. لا تفوّت فرصتك! #RMCScholarship", "en": "REMINDER 📢 Scholarship applications for the 2025/2026 academic year close on June 30th. Apply now at our website. All Muslim students from Rwanda are eligible. Don''t miss your chance! #RMCScholarship", "rw": "URWIBUTSO 📢 Gusaba buruse y''umwaka w''amashuri wa 2025/2026 bifunga ku ya 30 Kamena. Saba ubu kuri urubuga rwacu. Abanyeshuri bose b''Abayisilamu bo mu Rwanda barabyemerewe. Ntukabure amahirwe yawe! #RMCScholarship"}, "comments": "156", "platform": "twitter"}, {"date": "1d ago", "image": "https://images.unsplash.com/photo-1532629345422-7515f3d16bb6?q=80&w=600&auto=format&fit=crop", "likes": "2.3K", "handle": "@rmc_rwanda", "content": {"ar": "حملتنا لتوزيع الطعام في رمضان حققت نجاحًا كبيرًا! وزّعنا معًا 5,000 طرد غذائي على الأسر المحتاجة في جميع المقاطعات الخمس. جزاكم الله خيرًا لكل المتطوعين والمتبرعين! ❤️", "en": "Our Ramadan food drive was a huge success! Together we distributed 5,000 food packages to families in need across all 5 provinces. JazakAllahu Khairan to all volunteers and donors! ❤️", "rw": "Igikorwa cyacu cyo gutanga ibiribwa muri Ramadan cyagenze neza cyane! Hamwe twatanze ibyfunyiko 5,000 by''ibiribwa ku miryango ikennye mu ntara zose 5. JazakAllahu Khairan ku bakorerabushake bose n''abaterankunga! ❤️"}, "comments": "412", "platform": "instagram"}], "title": {"ar": "أحدث ما لدينا على وسائل التواصل الاجتماعي", "en": "Latest on Social Media", "rw": "Ibyacu bishya ku mbuga nkoranyambaga"}, "eyebrow": {"ar": "وسائل التواصل الاجتماعي", "en": "Social Media", "rw": "Imbuga nkoranyambaga"}, "channels": [{"key": "facebook", "href": "#", "label": "Facebook", "followers": "24.5K"}, {"key": "twitter", "href": "#", "label": "Twitter / X", "followers": "12.8K"}, {"key": "instagram", "href": "#", "label": "Instagram", "followers": "18.2K"}, {"key": "youtube", "href": "#", "label": "YouTube", "followers": "8.4K"}], "subtitle": {"ar": "تابع المجتمع الإسلامي الرواندي على وسائل التواصل الاجتماعي لتبقى على اطلاع بأحدث الأخبار والفعاليات وقصص المجتمع.", "en": "Follow RMC on social media to stay updated with the latest news, events, and community stories.", "rw": "Kurikira RMC ku mbuga nkoranyambaga kugira ngo uhore umenya amakuru mashya, ibikorwa, n''inkuru z''umuryango."}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:07.677182+00', '2026-06-18 10:35:49.376796+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('5a9d3a1f-e7af-4842-8159-4ce0f4ab1c11', 'hero', '{"salam": "السَّلَامُ عَلَيْكُمْ", "slides": ["https://pbs.twimg.com/media/HEQLxPtaUAADjH2?format=jpg&name=large", "https://pbs.twimg.com/media/HESeGQZWAAAvdtq?format=jpg&name=large"], "headline": {"ar": "مرحبًا بكم في المجتمع الإسلامي الرواندي", "en": "Welcome to the Rwanda Muslim Community", "rw": "Murakaza neza mu Muryango w''Abayisilamu bo mu Rwanda"}, "subtitle": {"ar": "إيمانٌ وعِلمٌ وخدمة — نوحّد المجتمع المسلم في رواندا ونرتقي به.", "en": "Faith, knowledge, and service — uniting and uplifting the Muslim community across Rwanda.", "rw": "Ukwemera, ubumenyi no gufasha — guhuza no guteza imbere umuryango w''Abayisilamu mu Rwanda hose."}, "primaryCta": {"ar": "اطلب خدمة", "en": "Request a Service", "rw": "Saba serivisi"}, "primaryHref": "/services", "secondaryCta": {"ar": "آخر الأنشطة", "en": "Trends", "rw": "Ibikorwa"}, "secondaryHref": "/activities"}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:23:09.237229+00', '2026-06-18 10:35:35.897456+00') ON CONFLICT DO NOTHING;
INSERT INTO public.site_content (id, section_key, value, updated_by, created_at, updated_at) VALUES ('a0f7ad60-3a83-4ed4-afeb-44a09b1129a4', 'areas', '{"lede": {"ar": "يعمل المجتمع الإسلامي الرواندي عبر أربع ركائز استراتيجية للنهوض بالمجتمع المسلم في رواندا وتعليمه وربطه — من المساجد المحلية إلى الشراكات العالمية.", "en": "RMC works across four strategic pillars to uplift, educate, and connect the Muslim community of Rwanda — from local mosques to global partnerships.", "rw": "RMC ikorera mu nkingi enye z''ingenzi mu guteza imbere, kwigisha no guhuza umuryango w''Abayisilamu wo mu Rwanda — kuva mu misigiti yo mu turere kugeza ku bufatanye mpuzamahanga."}, "items": [{"icon": "BookOpen", "title": {"ar": "الدعوة", "en": "Dawah", "rw": "Kwamamaza Idini"}, "description": {"ar": "نشر تعاليم الإسلام الصحيحة من خلال الدعوة السلمية والإرشاد.", "en": "Spreading the true teachings of Islam through peaceful outreach and guidance.", "rw": "Gukwirakwiza inyigisho z''ukuri za Isilamu binyuze mu kugera ku bantu mu mahoro no kuyobora."}}, {"icon": "Heart", "title": {"ar": "التنمية الاجتماعية", "en": "Socio Development", "rw": "Iterambere ry''Imibereho"}, "description": {"ar": "تمكين المجتمعات من خلال الصحة ومكافحة الفقر ومبادرات الرعاية الاجتماعية.", "en": "Empowering communities through health, poverty alleviation, and welfare initiatives.", "rw": "Guha imbaraga abaturage binyuze mu buzima, kurwanya ubukene, n''ibikorwa byo guteza imbere imibereho."}}, {"icon": "GraduationCap", "title": {"ar": "التعليم", "en": "Education", "rw": "Uburezi"}, "description": {"ar": "توفير تعليم عام وإسلامي عالي الجودة للشباب في جميع أنحاء البلاد.", "en": "Providing quality secular and Islamic education to the youth across the nation.", "rw": "Gutanga uburezi bw''isi n''ubwa Isilamu bufite ireme ku rubyiruko mu gihugu hose."}}, {"icon": "Globe", "title": {"ar": "الشؤون الخارجية", "en": "Foreign Affairs", "rw": "Imibanire n''Amahanga"}, "description": {"ar": "بناء علاقات وشراكات دولية قوية والحفاظ عليها.", "en": "Building and maintaining strong international relations and partnerships.", "rw": "Kubaka no kubungabunga imibanire n''ubufatanye mpuzamahanga bukomeye."}}], "title": {"ar": "مجالات", "en": "Areas of", "rw": "Inzego z''"}, "eyebrow": {"ar": "أثرنا", "en": "Our Impact", "rw": "Ingaruka zacu"}, "titleAccent": {"ar": "التدخل", "en": "Intervention", "rw": "Ibikorwa"}}', '169547b8-62c9-4251-ad44-f648d6ab9ab2', '2026-06-18 08:22:59.487272+00', '2026-06-18 10:35:39.235735+00') ON CONFLICT DO NOTHING;
